106	    /// There is no easy way to get original record batch size from Arrow metadata.
107	    /// Let's just use the number of bytes read from read buffer.
108	    auto batch_end = getDataOffsetMaybeCompressed(*in);
109	    if (batch_end > batch_start)
110	        approx_bytes_read_for_chunk = batch_end - batch_start;
111	    return res;
