131	static std::shared_ptr<arrow::RecordBatchReader> createStreamReader(ReadBuffer & in)
132	{
133	    auto options = arrow::ipc::IpcReadOptions::Defaults();
134	    options.memory_pool = ArrowMemoryPool::instance();
135	    auto stream_reader_status = arrow::ipc::RecordBatchStreamReader::Open(std::make_unique<ArrowInputStreamFromReadBuffer>(in), options);
136	    if (!stream_reader_status.ok())
137	        throw Exception(ErrorCodes::UNKNOWN_EXCEPTION,
138	                        "Error while opening a table: {}", stream_reader_status.status().ToString());
139	    return *stream_reader_status;
140	}
