592	      const auto offsets = data.GetValues<offset_type>(1);
593	      const Buffer& values = *data.buffers[2];
594	
595	      const auto first_offset = offsets[0];
596	      const auto last_offset = offsets[data.length];
597	      // This early test avoids undefined behaviour when computing `data_extent`
598	      if (first_offset < 0 || last_offset < 0) {
599	        return Status::Invalid("Negative offsets in binary array");
600	      }
