620	    int64_t views_byte_size = data.buffers[1]->size();
621	    int64_t required_view_count = data.length + data.offset;
622	    if (static_cast<int64_t>(views_byte_size / BinaryViewType::kSize) <
623	        required_view_count) {
624	      return Status::Invalid("View buffer size (bytes): ", views_byte_size,
625	                             " isn't large enough for length: ", data.length,
626	                             " and offset: ", data.offset);
627	    }
628	
629	    if (!full_validation) return Status::OK();
630	
631	    auto CheckPrefix = [&](size_t i,
632	                           std::array<uint8_t, BinaryViewType::kPrefixSize> prefix,
633	                           const uint8_t* data) {
634	      if (std::memcmp(data, prefix.data(), BinaryViewType::kPrefixSize) == 0) {
635	        return Status::OK();
636	      }
637	      return Status::Invalid("View at slot ", i, " has inlined prefix 0x",
638	                             HexEncode(prefix.data(), BinaryViewType::kPrefixSize),
639	                             " but the out-of-line data begins with 0x",
640	                             HexEncode(data, BinaryViewType::kPrefixSize));
641	    };
642	
643	    util::span views(data.GetValues<BinaryViewType::c_type>(1),
644	                     static_cast<size_t>(data.length));
645	    util::span data_buffers(data.buffers.data() + 2, data.buffers.size() - 2);
646	
647	    for (size_t i = 0; i < static_cast<size_t>(data.length); ++i) {
648	      if (data.IsNull(i)) continue;
649	
650	      if (views[i].size() < 0) {
651	        return Status::Invalid("View at slot ", i, " has negative size ",
652	                               views[i].size());
653	      }
654	
655	      if (views[i].is_inline()) {
656	        auto padding_bytes = util::span(views[i].inlined.data).subspan(views[i].size());
657	        for (auto padding_byte : padding_bytes) {
658	          if (padding_byte != 0) {
659	            return Status::Invalid("View at slot ", i, " was inline with size ",
660	                                   views[i].size(),
661	                                   " but its padding bytes were not all zero: ",
662	                                   HexEncode(padding_bytes.data(), padding_bytes.size()));
663	          }
664	        }
665	        continue;
666	      }
667	
668	      auto [size, prefix, buffer_index, offset] = views[i].ref;
669	
670	      if (buffer_index < 0) {
671	        return Status::Invalid("View at slot ", i, " has negative buffer index ",
672	                               buffer_index);
673	      }
674	
675	      if (offset < 0) {
676	        return Status::Invalid("View at slot ", i, " has negative offset ", offset);
677	      }
678	
679	      if (static_cast<size_t>(buffer_index) >= data_buffers.size()) {
680	        return Status::IndexError("View at slot ", i, " references buffer ", buffer_index,
681	                                  " but there are only ", data_buffers.size(),
682	                                  " data buffers");
683	      }
684	      const auto& buffer = data_buffers[buffer_index];
685	
686	      if (int64_t end = offset + static_cast<int64_t>(size); end > buffer->size()) {
687	        return Status::IndexError(
688	            "View at slot ", i, " references range ", offset, "-", end, " of buffer ",
689	            buffer_index, " but that buffer is only ", buffer->size(), " bytes long");
690	      }
