917	                             " isn't large enough for length: ", data.length,
918	                             " and offset: ", data.offset);
919	    }
920	    if constexpr (is_list_view) {
921	      const auto required_sizes = data.length + data.offset;
922	      const auto sizes_bytes_size = data.buffers[2]->size();
