/// List / LargeList offsets must be monotonically non-decreasing and stay within the
/// child ("values") array. Arrow's cheap Validate() only checks the first and last
/// offset, but ClickHouse (readOffsetsFromArrowListColumn) and arrow::ListArray::Flatten
/// both assume every intermediate offset is monotonic; a decreasing pair would underflow
/// the computed element count and produce a corrupted array that reads out of bounds.
template <typename ListArrayType>
void checkArrowListOffsets(const arrow::Array & array)
{
    const auto & list = static_cast<const ListArrayType &>(array);
    const auto values = list.values();
    const int64_t values_length = values ? values->length() : 0;
    const int64_t length = list.length();
    for (int64_t i = 0; i < length; ++i)
    {
        const int64_t offset = static_cast<int64_t>(list.value_offset(i));
        const int64_t element_length = static_cast<int64_t>(list.value_length(i));
        if (element_length < 0 || offset < 0 || offset > values_length - element_length)
            throw Exception(
                ErrorCodes::INCORRECT_DATA,
                "Arrow {} array has corrupted offsets: element {} spans [{}, {}) but child array has {} elements",
                array.type()->ToString(), i, offset, offset + element_length, values_length);
    }
}

/// Extra structural checks that Arrow's cheap (non-full) Validate() does not perform but
/// which ClickHouse relies on to avoid out-of-bounds reads. We deliberately avoid running
/// full validation on arbitrary columns, because ClickHouse can emit spec-legal-but-
/// "invalid" data (for example non-UTF8 bytes inside an Arrow utf8 column when
/// output_string_as_string is enabled) that a full validation would wrongly reject.
void checkArrowArrayExtra(const arrow::Array & array)
{
    switch (array.type_id())
    {
        case arrow::Type::LIST:
            checkArrowListOffsets<arrow::ListArray>(array);
            break;
        case arrow::Type::LARGE_LIST:
            checkArrowListOffsets<arrow::LargeListArray>(array);
            break;
        case arrow::Type::STRING_VIEW:
        case arrow::Type::BINARY_VIEW:
        {
            /// View arrays keep per-element offset/length fields that reference the
            /// variadic data buffers; only full validation bounds-checks them (and rejects
            /// negative sizes). ClickHouse never writes view types, so this cannot cause
            /// false positives on round-tripped data.
            const auto status = array.ValidateFull();
            if (!status.ok())
                throw Exception(
                    ErrorCodes::INCORRECT_DATA, "Arrow view column failed validation: {}", status.ToString());
            break;
        }
        default:
            break;
    }

    /// Recurse into nested children (struct fields, list values, map entries).
    for (const auto & child_data : array.data()->child_data)
        checkArrowArrayExtra(*arrow::MakeArray(child_data));
}

/// Validate a record batch before it is turned into a Table and read into ClickHouse
/// columns. This must happen before arrow::Table::FromRecordBatches, because building the
/// table sums per-chunk null counts, which scans each validity bitmap over its declared
/// length and would read out of bounds on a truncated bitmap. It also happens before any
/// ClickHouse-side memory reservation, so a malformed declared length is reported as
/// INCORRECT_DATA rather than a memory-allocation failure.
void validateArrowRecordBatch(const arrow::RecordBatch & batch)
{
    /// Cheap validation: verifies every buffer (values, offsets, validity bitmap, view
    /// buffers) is large enough for the declared length, that lengths are non-negative and
    /// do not overflow, and that nested child lengths are consistent with their parents.
    /// It validates the validity bitmap size *without* scanning it, so it is safe to run
    /// before Arrow computes null counts.
    const auto status = batch.Validate();
    if (!status.ok())
        throw Exception(ErrorCodes::INCORRECT_DATA, "Arrow record batch failed validation: {}", status.ToString());

    for (int i = 0; i < batch.num_columns(); ++i)
        checkArrowArrayExtra(*batch.column(i));
}

